import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { listEnterpriseMemberships } from "../handlers/listEnterpriseMemberships";
import type { ApiError } from "../runtime/client";

type Data = Awaited<ReturnType<typeof listEnterpriseMemberships>>;

export function useListEnterpriseMemberships(
  bookmark?: string | null,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["listEnterpriseMemberships", bookmark],
    queryFn: () => listEnterpriseMemberships(bookmark),
    ...options,
  });
}
